    const cors = require('cors');
    const bodyParser = require('body-parser');

    const app = express();
    const port = process.env.PORT || 5000;

    app.use(cors());
    app.use(bodyParser.json());

    let data = [
        { id: 1, name: 'Item 1', description: 'Description 1' },
        { id: 2, name: 'Item 2', description: 'Description 2' }
