class Task:
    """Represents a single task."""
    def __init__(self, func: Callable[[Any], Any], name: str = "Task"):
        self.func = func
        self.name = name

    def __repr__(self):
        return f"Task({self.name})"

    def execute(self, input_data: Any) -> Any:
        """Executes the task and returns the result."""
        return self.func(input_data)


class Pipe:
    """Connects the output of one task to the input of another."""
    def __init__(self, task1: Task, task2: Task):
        self.task1 = task1
        self.task2 = task2

    def connect(self, input_data: Any) -> Any:
        """Executes task1, then task2 with task1's output as input."""
        intermediate_result = self.task1.execute(input_data)
        return self.task2.execute(intermediate_result)


